fun pages(url: String): Flow<Page> = flow {
    var next: String? = url
    while (next != null) {
        val page = fetch(next)      // suspending I/O per element
        emit(page)                  // one page per collector demand
        next = page.next
    }
}

pages("/api/items").take(2).collect { println(it.size) }
